<?php $title='Detalhes do módulo'; ?>
<section class="page-head"><div><h1><?= e($project['name']) ?></h1><p><?= e($project['full_name']?:$project['description']) ?></p></div><div><?php if($project['admin_url']): ?><a class="btn primary" href="<?= e($project['admin_url']) ?>" target="_blank" rel="noopener noreferrer">Administrar</a><?php endif; ?> <a class="btn" href="<?= e(base_url('projetos/'.$project['id'].'/editar')) ?>">Editar módulo</a></div></section>
<?php if($project['status']==='deploying'): ?><div class="alert warning">Módulo em implantação. O endereço administrativo pode ainda estar indisponível; isso não afeta a GDA Plataforma.</div><?php endif; ?>
<div class="detail-grid"><section class="panel"><h2>Informações do módulo</h2><dl><dt>Nome</dt><dd><?= e($project['name']) ?></dd><dt>Nome completo</dt><dd><?= e($project['full_name']?:'Não informado') ?></dd><dt>Identificador</dt><dd><code><?= e($project['code']) ?></code></dd><dt>Descrição</dt><dd><?= e($project['description']) ?></dd><dt>Categoria</dt><dd><?= e($project['category']?:'Não informada') ?></dd><dt>Versão</dt><dd>v<?= e($project['version']) ?></dd><dt>Status</dt><dd><span class="badge <?= e($project['status']) ?>"><?= e(project_status_label($project['status'])) ?></span></dd><dt>URL pública</dt><dd><?php if($project['url']): ?><a href="<?= e($project['url']) ?>" target="_blank" rel="noopener noreferrer"><?= e($project['url']) ?></a><?php else: ?>Não configurada<?php endif; ?></dd><dt>URL administrativa</dt><dd><?= e($project['admin_url']?:'Não configurada') ?></dd><dt>Clientes vinculados</dt><dd><?= count($clients) ?></dd><dt>Criado em</dt><dd><?= e(date('d/m/Y H:i',strtotime($project['created_at']))) ?></dd><dt>Atualizado em</dt><dd><?= e(date('d/m/Y H:i',strtotime($project['updated_at']))) ?></dd></dl></section>
<section class="panel"><h2>Clientes com acesso</h2><?php if(!$clients): ?><div class="empty">Nenhum cliente vinculado.</div><?php else: ?><div class="project-list"><?php foreach($clients as $c): ?><a href="<?= e(base_url('clientes/'.$c['id'])) ?>"><b><?= e($c['name']) ?></b><small><?= e($c['identifier']) ?></small></a><?php endforeach; ?></div><?php endif; ?></section></div>
<section class="panel"><h2>Atividade recente</h2><?php if(!$activities): ?><div class="empty">Nenhuma atividade recente deste módulo.</div><?php else: ?><div class="timeline"><?php foreach($activities as $activity): ?><div><span class="dot"></span><p><b><?= e($activity['user_name']??'Sistema') ?></b> — <?= e($activity['description']) ?><small><?= e(date('d/m/Y H:i',strtotime($activity['created_at']))) ?></small></p></div><?php endforeach; ?></div><?php endif; ?></section>
<section class="panel future-panel"><h2>Integrações futuras</h2><p>Espaço reservado para planos e licenças, modalidades, saúde do módulo, versão instalada, atualizações, provisionamento e acesso integrado do Super Administrador.</p><small>Nenhuma dessas integrações está ativa nesta fase.</small></section>
